// Obtener todos los eventos recibidos
const events = $input.all();

// Transformar a formato limpio
const cleanEvents = events.map(e => {
  const ev = e.json;

  return {
    json: {
      id: ev.id,
      titulo: ev.summary || "",
      inicio: ev.start?.dateTime || ev.start?.date || "",
      fin: ev.end?.dateTime || ev.end?.date || "",
      calendario: ev.organizer?.displayName || "",
      creadoPor: ev.creator?.email || "",
      estado: ev.status || ""
    }
  };
});

return cleanEvents;

// Get appointment data from Webhook node
const appointment = $('Webhook1').item.json.body;

// Get client/vehicle data from DB node
const client = $('get_user_bdd').item.json;

// Use timezone only as label (no conversion)
const timeZone = 'America/Argentina/Buenos_Aires';

// Build full client name safely
const fullName = client.full_name || 
  `${client.first_name || ''} ${client.last_name || ''}`.trim();

// Build description
const description = `
👤 Cliente: ${fullName}
📧 Email: ${client.email || 'No informado'}
📞 Teléfono: ${client.phone || client.mobile || 'No informado'}
🆔 DNI: ${client.dni || 'No informado'}

🚗 Vehículo: ${client.company_name || ''} ${client.model || ''}
🔢 Patente: ${client.license_plate || 'No informada'}
🧾 VIN: ${client.vin || 'No informado'}
🔧 Motor: ${client.engine_number || 'No informado'}

🛠 Operación: ${appointment.operation_type}


📏 KM: ${appointment.km_at_appointment || 'No informado'}
💰 Precio estimado: $${appointment.estimated_price || 0}
💵 Precio final: $${appointment.final_price || 0}
💳 Método de pago: ${appointment.payment_method || 'No especificado'}

📌 Estado: ${appointment.status}
`.trim();

// Return clean Google Calendar object
return {
  summary: `Turno - ${fullName} - ${client.license_plate || ''}`,

  description,

  start: {
    dateTime: appointment.actual_start_time,
    timeZone
  },

  end: {
    dateTime: appointment.actual_end_time,
    timeZone
  },

  extendedProperties: {
    private: {
      appointment_id: appointment.id,
      client_id: client.client_id,
      advisor_id: appointment.advisor_id,
      branch_id: appointment.branch_id,
      workshop_id: appointment.workshop_id,
      google_event_id: appointment.google_event_id || '',
      customer_code: client.customer_code
    }
  }
};

const event = $input.item.json;

return {
  google_event_id: event.id,
  organizer_email: event.organizer?.email || null
};

// ==================================== 
// OBTENER NEXT ID
// ==================================== 
const filas = $input.all();
if (!filas || filas.length === 0) {
  return [{ nextId: 1 }];
}
const ids = filas.map(fila => {
  const valor = Object.values(fila.json)[1];
  return parseInt(valor) || 0;
});
const maxId = Math.max(...ids);
const nextId = maxId + 1;
// ==================================== 
// OBTENER FERIADOS
// ==================================== 
const feriados = $("feriados").all().map(item => item.json.fecha_iso);
// ==================================== 
// FUNCIONES AUXILIARES
// ==================================== 
function formatearFecha(date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}
function esFeriado(date) {
  return feriados.includes(formatearFecha(date));
}
function esFinDeSemana(date) {
  const d = date.getDay();
  return d === 0 || d === 6;
}
// ==================================== 
// FECHA ACTUAL ARGENTINA
// ==================================== 
const ahora = new Date();
const partes = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Argentina/Buenos_Aires',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  hour12: false
}).formatToParts(ahora);
const get = (type) => partes.find(p => p.type === type).value;
const year  = parseInt(get('year'));
const month = parseInt(get('month')) - 1;
const day   = parseInt(get('day'));
const hour  = parseInt(get('hour'));
const minute = parseInt(get('minute'));
const horaActual = hour + minute / 60;
let fechaEntrega = new Date(year, month, day);
fechaEntrega.setHours(0, 0, 0, 0);
const hoyStr = formatearFecha(fechaEntrega);
const diaSemana = fechaEntrega.getDay();
// ==================================== 
// FUNCIÓN: sábado inmediato (día siguiente a hoy)
// ==================================== 
function esSabadoInmediato(fecha) {
  const manana = new Date(year, month, day);
  manana.setDate(manana.getDate() + 1);
  return formatearFecha(fecha) === formatearFecha(manana);
}
// ==================================== 
// 🔥 EXCEPCION SEMANA SANTA
// ==================================== 
if (hoyStr === "2026-04-01" || (hoyStr === "2026-04-02" && horaActual <= 12)) {
  return [{ nextId: $("When Executed by Another Workflow").item.json.from, turno: "2026-04-02" }];
}
if ((hoyStr === "2026-04-02" && horaActual > 12) || hoyStr === "2026-04-03") {
  return [{ nextId: $("When Executed by Another Workflow").item.json.from, turno: "2026-04-06" }];
}
if (hoyStr === "2026-04-04" && horaActual <= 12) {
  return [{ nextId: $("When Executed by Another Workflow").item.json.from, turno: "2026-04-04" }];
}
if (hoyStr === "2026-04-04" && horaActual > 12) {
  return [{ nextId: $("When Executed by Another Workflow").item.json.from, turno: "2026-04-06" }];
}
// ==================================== 
// LÓGICA NORMAL
// ==================================== 
if (diaSemana === 0) {
  // Domingo → mover a lunes
  fechaEntrega.setDate(fechaEntrega.getDate() + 1);
} else if (diaSemana === 6) {
  // Sábado después de las 12:30 → mover a lunes
  if (horaActual > 12.5) {
    fechaEntrega.setDate(fechaEntrega.getDate() + 2);
  }
  // Sábado hasta las 12:30 → entrega hoy (no se mueve)
} else {
  // Lunes a viernes
  if (horaActual > 18) {
    if (diaSemana === 5) {
      // Viernes después de las 18 → sábado
      fechaEntrega.setDate(fechaEntrega.getDate() + 1);
    } else {
      // Lunes-jueves después de las 18 → día siguiente
      fechaEntrega.setDate(fechaEntrega.getDate() + 1);
    }
  }
}
// ==================================== 
// AJUSTE GENERAL
// Salta domingos siempre, feriados siempre,
// sábados EXCEPTO: si es hoy antes de las 12:30
//                  o si es el sábado inmediato (día siguiente a hoy)
// ==================================== 
while (
  esFeriado(fechaEntrega) ||
  fechaEntrega.getDay() === 0 ||
  (fechaEntrega.getDay() === 6 && !(
    (formatearFecha(fechaEntrega) === hoyStr && horaActual <= 12.5) ||
    esSabadoInmediato(fechaEntrega)
  ))
) {
  fechaEntrega.setDate(fechaEntrega.getDate() + 1);
}
// ==================================== 
// RESULTADO
// ==================================== 
return [{
  nextId: $("When Executed by Another Workflow").first().json.from,
  turno: formatearFecha(fechaEntrega)
}];

